/// <reference path="./manga-provider.d.ts" />

class Provider {
    private baseUrl = "https://mangafire.to";

    getSettings(): Settings {
        return {
            supportsMultiLanguage: true,
            supportsMultiScanlator: true,
        };
    }

    private async apiRequest(url: string): Promise<any> {
        const response = await fetch(url, {
            method: "GET",
            headers: {
                "Accept": "application/json",
                "User-Agent": "Mozilla/5.0",
                "Referer": this.baseUrl + "/",
            },
        });

        if (!response.ok) {
            throw new Error("MangaFire API HTTP " + response.status);
        }

        return await response.json();
    }

    private mangaIdFromUrl(url: string): string {
        const clean = String(url || "").split("?")[0].replace(/\/+$/, "");
        const last = clean.split("/").pop() || "";

        // Current MangaFire URLs look like:
        // /title/kx6xr-life-of-a-demon-hunter
        // Older URLs can look like:
        // /manga/life-of-a-demon-hunter.kx6xr
        if (clean.includes("/title/")) {
            return last.split("-", 2)[0];
        }

        if (clean.includes("/manga/") && last.includes(".")) {
            return last.split(".").pop() || "";
        }

        return last.split("-", 2)[0];
    }

    async search(opts: QueryOptions): Promise<SearchResult[]> {
        const url =
            this.baseUrl +
            "/api/titles?keyword=" +
            encodeURIComponent(opts.query) +
            "&language=en&limit=30&page=1";

        const json = await this.apiRequest(url);
        const items = Array.isArray(json.items) ? json.items : [];

        return items
            .map((item: any) => {
                const sourceUrl = String(item.url || "");
                const id = this.mangaIdFromUrl(sourceUrl);

                return {
                    id: id,
                    title: String(item.title || ""),
                    synonyms: [],
                    image: item.poster
                        ? (item.poster.medium || item.poster.large || item.poster.small)
                        : undefined,
                };
            })
            .filter((item: SearchResult) => !!item.id && !!item.title);
    }

    async findChapters(mangaId: string): Promise<ChapterDetails[]> {
        const chapters: ChapterDetails[] = [];
        const seen = new Set<string>();

        const apiUrl =
            this.baseUrl +
            "/api/titles/" +
            encodeURIComponent(mangaId) +
            "/chapters";

        const limit = 200;
        let page = 1;
        let hasNext = true;

        while (hasNext && page <= 100) {
            const url =
                apiUrl +
                "?language=en&sort=number&order=desc&limit=" +
                limit +
                "&page=" +
                page;

            const json = await this.apiRequest(url);
            const items = Array.isArray(json.items) ? json.items : [];

            for (const item of items) {
                const id = String(item.id ?? "");
                if (!id || seen.has(id)) {
                    continue;
                }

                seen.add(id);

                const number = item.number != null
                    ? String(item.number)
                    : "";

                const language = String(item.language || "en");

                const title = ["Ch. " + number, item.name]
                    .filter(Boolean)
                    .join(": ");

                chapters.push({
                    id: id,
                    url:
                        this.baseUrl +
                        "/title/" +
                        encodeURIComponent(mangaId) +
                        "/" +
                        encodeURIComponent(id) +
                        "-chapter-" +
                        encodeURIComponent(number) +
                        "-" +
                        encodeURIComponent(language),
                    title: title || "Chapter",
                    chapter: number,
                    index: 0,
                    scanlator: item.type === "official"
                        ? "official"
                        : undefined,
                    language: language,
                    updatedAt: item.createdAt
                        ? new Date(Number(item.createdAt) * 1000).toISOString()
                        : undefined,
                });
            }

            hasNext = !!(json.meta && json.meta.hasNext);
            page++;
        }

        // API returns newest first. Seanime expects oldest -> newest.
        chapters.reverse();

        for (let i = 0; i < chapters.length; i++) {
            chapters[i].index = i;
        }

        return chapters;
    }

    async findChapterPages(chapterId: string): Promise<ChapterPage[]> {
        const json = await this.apiRequest(
            this.baseUrl +
            "/api/chapters/" +
            encodeURIComponent(chapterId)
        );

        const pages =
            json &&
            json.data &&
            Array.isArray(json.data.pages)
                ? json.data.pages
                : [];

        return pages
            .map((page: any, index: number) => ({
                url: String(page.url || ""),
                index: index,
                headers: {
                    "Referer": this.baseUrl + "/",
                },
            }))
            .filter((page: ChapterPage) => !!page.url);
    }
}
